import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useNotification } from './NotificationContext';

const Onboarding = () => {
  const { user, completeOnboarding } = useAuth();
  const navigate = useNavigate();
  const { addNotification } = useNotification();
  
  const [currentStep, setCurrentStep] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    major: '',
    studyGoals: '',
    dailyStudyTarget: 120, // Default 2 hours in minutes
    preferredStudyTime: 'morning',
    subjects: [''],
    weeklyGoals: {
      monday: true,
      tuesday: true,
      wednesday: true,
      thursday: true,
      friday: true,
      saturday: false,
      sunday: false
    }
  });
  
  const steps = [
    'Basic Information',
    'Study Goals',
    'Study Schedule',
    'Subjects'
  ];
  
  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    if (type === 'checkbox') {
      setFormData(prev => ({
        ...prev,
        weeklyGoals: {
          ...prev.weeklyGoals,
          [name]: checked
        }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }
  };
  
  const handleAddSubject = () => {
    setFormData(prev => ({
      ...prev,
      subjects: [...prev.subjects, '']
    }));
  };
  
  const handleRemoveSubject = (index) => {
    setFormData(prev => ({
      ...prev,
      subjects: prev.subjects.filter((_, i) => i !== index)
    }));
  };
  
  const handleSubjectChange = (index, value) => {
    setFormData(prev => {
      const newSubjects = [...prev.subjects];
      newSubjects[index] = value;
      return {
        ...prev,
        subjects: newSubjects
      };
    });
  };
  
  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };
  
  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    try {
      // Filter out empty subjects
      const filteredSubjects = formData.subjects.filter(subject => subject.trim() !== '');
      
      const userPreferences = {
        major: formData.major,
        study_goals: formData.studyGoals,
        daily_study_target: formData.dailyStudyTarget,
        preferred_study_time: formData.preferredStudyTime,
        subjects: filteredSubjects,
        weekly_goals: formData.weeklyGoals
      };
      
      const result = await completeOnboarding(userPreferences);
      
      if (!result.success) {
        addNotification('Could not complete onboarding. Please try again.', 'error');
        return;
      }
      
      addNotification('Onboarding completed successfully!', 'success');
      navigate('/dashboard');
    } catch (error) {
      console.error('Error completing onboarding:', error);
      addNotification('An error occurred. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };
  
  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-white">Basic Information</h2>
            <p className="text-white/70 text-sm">Let's start with some basic information about your studies.</p>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="major" className="block text-white text-sm font-medium mb-1">
                  What are you studying?
                </label>
                <input
                  type="text"
                  id="major"
                  name="major"
                  value={formData.major}
                  onChange={handleInputChange}
                  className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                  placeholder="e.g. Computer Science, Medicine, etc."
                  required
                />
              </div>
            </div>
          </div>
        );
        
      case 1:
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-white">Study Goals</h2>
            <p className="text-white/70 text-sm">Tell us about your study goals.</p>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="studyGoals" className="block text-white text-sm font-medium mb-1">
                  What are your study goals?
                </label>
                <textarea
                  id="studyGoals"
                  name="studyGoals"
                  value={formData.studyGoals}
                  onChange={handleInputChange}
                  className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                  placeholder="e.g. Get straight A's, prepare for exams, etc."
                  rows="3"
                />
              </div>
              
              <div>
                <label htmlFor="dailyStudyTarget" className="block text-white text-sm font-medium mb-1">
                  Daily study target (minutes)
                </label>
                <input
                  type="number"
                  id="dailyStudyTarget"
                  name="dailyStudyTarget"
                  value={formData.dailyStudyTarget}
                  onChange={handleInputChange}
                  min="15"
                  max="720"
                  step="15"
                  className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                />
                <p className="text-xs text-white/60 mt-1">
                  {Math.floor(formData.dailyStudyTarget / 60)} hours and {formData.dailyStudyTarget % 60} minutes per day
                </p>
              </div>
            </div>
          </div>
        );
        
      case 2:
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-white">Study Schedule</h2>
            <p className="text-white/70 text-sm">Let us know your preferred study times.</p>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="preferredStudyTime" className="block text-white text-sm font-medium mb-1">
                  When do you prefer to study?
                </label>
                <select
                  id="preferredStudyTime"
                  name="preferredStudyTime"
                  value={formData.preferredStudyTime}
                  onChange={handleInputChange}
                  className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                >
                  <option value="morning">Morning</option>
                  <option value="afternoon">Afternoon</option>
                  <option value="evening">Evening</option>
                  <option value="night">Night</option>
                  <option value="varies">Varies</option>
                </select>
              </div>
              
              <div>
                <p className="block text-white text-sm font-medium mb-2">Days you plan to study</p>
                <div className="grid grid-cols-4 gap-2">
                  {Object.entries(formData.weeklyGoals).map(([day, checked]) => (
                    <div key={day} className="flex items-center">
                      <input
                        type="checkbox"
                        id={day}
                        name={day}
                        checked={checked}
                        onChange={handleInputChange}
                        className="h-4 w-4 text-blue-600 rounded border-gray-600 focus:ring-blue-500"
                      />
                      <label htmlFor={day} className="ml-2 text-sm text-white/80 capitalize">
                        {day}
                      </label>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
        
      case 3:
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-white">Your Subjects</h2>
            <p className="text-white/70 text-sm">Add the subjects you're studying.</p>
            
            <div className="space-y-4">
              {formData.subjects.map((subject, index) => (
                <div key={index} className="flex space-x-2">
                  <input
                    type="text"
                    value={subject}
                    onChange={(e) => handleSubjectChange(index, e.target.value)}
                    className="appearance-none rounded-lg relative block w-full px-3 py-3 border border-gray-700 bg-gray-900/40 text-white placeholder-gray-400 focus:outline-none focus:ring-neural-500 focus:border-neural-500 focus:z-10 sm:text-sm backdrop-blur-sm"
                    placeholder={`Subject ${index + 1}`}
                  />
                  {formData.subjects.length > 1 && (
                    <button
                      type="button"
                      onClick={() => handleRemoveSubject(index)}
                      className="px-3 py-3 rounded-lg bg-red-500/20 text-red-400 hover:bg-red-500/30 transition-colors"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                      </svg>
                    </button>
                  )}
                </div>
              ))}
              
              <button
                type="button"
                onClick={handleAddSubject}
                className="px-4 py-2 rounded-lg bg-blue-500/20 text-blue-400 hover:bg-blue-500/30 transition-colors flex items-center"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
                </svg>
                Add Subject
              </button>
            </div>
          </div>
        );
        
      default:
        return null;
    }
  };
  
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 py-12 px-4 sm:px-6 lg:px-8">
      <motion.div
        className="max-w-md w-full space-y-8 p-8 bg-gray-800 rounded-2xl shadow-xl backdrop-blur-lg bg-opacity-50 border border-gray-700"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <div className="text-center">
          <motion.h2
            className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.5 }}
          >
            Welcome, {user?.profile?.name || user?.name || 'Student'}!
          </motion.h2>
          <p className="mt-2 text-sm text-white/60">Let's set up your study profile</p>
        </div>
        
        {/* Progress indicator */}
        <div className="relative pt-4">
          <div className="flex items-center justify-between mb-2">
            {steps.map((step, index) => (
              <div 
                key={index} 
                className={`flex flex-col items-center ${
                  index <= currentStep ? 'text-blue-500' : 'text-gray-500'
                }`}
              >
                <div 
                  className={`rounded-full h-8 w-8 flex items-center justify-center border-2 ${
                    index < currentStep 
                      ? 'bg-blue-500 border-blue-500 text-white' 
                      : index === currentStep 
                        ? 'border-blue-500 text-blue-500' 
                        : 'border-gray-700 text-gray-500'
                  }`}
                >
                  {index < currentStep ? (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                  ) : (
                    index + 1
                  )}
                </div>
                <span className="text-xs mt-1 hidden sm:block">{step}</span>
              </div>
            ))}
          </div>
          <div className="overflow-hidden h-2 mb-4 text-xs flex rounded bg-gray-700">
            <div 
              style={{ width: `${(currentStep / (steps.length - 1)) * 100}%` }} 
              className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-gradient-to-r from-cyan-500 to-blue-500"
            />
          </div>
        </div>
        
        <form onSubmit={handleSubmit} className="mt-8 space-y-6">
          {renderStepContent()}
          
          <div className="flex justify-between">
            {currentStep > 0 ? (
              <button
                type="button"
                onClick={handleBack}
                className="px-4 py-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600 transition-colors"
              >
                Back
              </button>
            ) : (
              <div></div>
            )}
            
            {currentStep < steps.length - 1 ? (
              <button
                type="button"
                onClick={handleNext}
                className="px-4 py-2 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-500 text-white hover:from-cyan-600 hover:to-blue-600 transition-colors"
              >
                Next
              </button>
            ) : (
              <motion.button
                type="submit"
                className="px-4 py-2 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-500 text-white hover:from-cyan-600 hover:to-blue-600 transition-colors"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                disabled={isLoading}
              >
                {isLoading ? (
                  <span className="flex items-center">
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Saving...
                  </span>
                ) : (
                  'Complete'
                )}
              </motion.button>
            )}
          </div>
        </form>
      </motion.div>
    </div>
  );
};

export default Onboarding; 